import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Troubleshoot Bedrock pack hosting","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/troubleshooting.md","filePath":"packages/bedrock-addon-manager/docs/troubleshooting.md","lastUpdated":1792252144000}`),a={name:`packages/bedrock-addon-manager/docs/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="troubleshoot-bedrock-pack-hosting" tabindex="-1">Troubleshoot Bedrock pack hosting <a class="header-anchor" href="#troubleshoot-bedrock-pack-hosting" aria-label="Permalink to “Troubleshoot Bedrock pack hosting”">​</a></h1><h2 id="players-cannot-download-a-pack" tabindex="-1">Players cannot download a pack <a class="header-anchor" href="#players-cannot-download-a-pack" aria-label="Permalink to “Players cannot download a pack”">​</a></h2><p>Start by checking that <code>web.enabled</code> is true and that <code>/baddon list</code> shows the pack. Then make sure the configured bind address and port are reachable through your server firewall. <code>web.public_url</code> must point to the address your clients can use. If it is empty, BedrockAddonManager can ask UPnPumpkin to forward the port when <code>web.port_forwarding</code> is enabled. If forwarding does not succeed, it uses a loopback address, which works only for players on the server machine.</p><p>The built-in server uses plain HTTP. To serve packs over HTTPS, put a reverse proxy in front of it and set <code>web.public_url</code> to the address clients use at the proxy. If you host packs elsewhere, set a <code>download_url</code> override for each pack; you can also turn off the built-in server with <code>web.enabled = false</code>.</p><h2 id="a-pack-is-missing-or-has-unexpected-metadata" tabindex="-1">A pack is missing or has unexpected metadata <a class="header-anchor" href="#a-pack-is-missing-or-has-unexpected-metadata" aria-label="Permalink to “A pack is missing or has unexpected metadata”">​</a></h2><p>BedrockAddonManager scans the pack folder at server startup and when you run <code>/baddon reload</code>. Check the server log for manifest errors, reload, and then use <code>/baddon list</code> to see what was found. An <code>.mcaddon</code> may contain both behavior and resource packs; the plugin extracts only resource packs. For those extracted packs, use the effective name shown by <code>/baddon list</code> as the override key. The inner filename may be different.</p><p>To leave out a pack, set <code>overrides.&quot;&lt;file&gt;&quot;.enabled = false</code>; you can also change its position with the <code>order</code> override. Config changes take effect after <code>/baddon reload</code> or a server restart. BedrockAddonManager does not edit <code>pumpkin.toml</code>.</p><h2 id="packs-are-not-offered-to-joining-players" tabindex="-1">Packs are not offered to joining players <a class="header-anchor" href="#packs-are-not-offered-to-joining-players" aria-label="Permalink to “Packs are not offered to joining players”">​</a></h2><p>BedrockAddonManager hosts pack files, but it does not send resource-pack offers when players join. That means clients are not prompted to download the packs, and setting <code>packs.force</code> has no effect.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};